import 'dart:convert';import 'package:geocoding/geocoding.dart';import 'package:geolocator/geolocator.dart';import 'package:get/get.dart';import '../models/responseModels/address_response_model.dart';import '../models/responseModels/auth_response_model.dart';import 'ConfigKeys.dart';class GeoUtil {  Future<Position> getCurrentPosition() async {    bool serviceEnabled;    LocationPermission permission;    serviceEnabled = await Geolocator.isLocationServiceEnabled();    if (!serviceEnabled) {      return Future.error('Location services are disabled.');    }    permission = await Geolocator.checkPermission();    if (permission == LocationPermission.denied) {      permission = await Geolocator.requestPermission();      if (permission == LocationPermission.denied) {        return Future.error('Location permissions are denied');      }    }    if (permission == LocationPermission.deniedForever) {      return Future.error(          'Location permissions are permanently denied, we cannot request permissions.');    }    return await Geolocator.getCurrentPosition(      desiredAccuracy: LocationAccuracy.high,    );  }  Future<Placemark?> getAddressFromLatLng(double latitude, double longitude) async {    try {      List<Placemark> placemarks = await placemarkFromCoordinates(latitude, longitude);      if (placemarks.isNotEmpty) {        return placemarks[0];      }    } catch (e) {      print("Error in getAddressFromLatLng: $e");    }    return null;  }  Future<LocationModel?> getApiAddress(double latitude, double longitude) async {    try {      final String url =          'https://maps.googleapis.com/maps/api/geocode/json?latlng=$latitude,$longitude&key=${ConfigKeys.googleMapKey}';      print(url);      final response = await GetConnect().get(url);      if (response.statusCode != 200) {        print("Failed to fetch address: ${response.statusCode}");        return null;      }      final body = json.decode(response.body);      final addressData = GoogleAddressResponse.fromJson(body);      String? getAddressComponent(String type) {        for (final result in addressData.results ?? []) {          for (final component in result.addressComponent ?? []) {            if (component.types?.contains(type) ?? false) {              return component.longName;            }          }        }        return null;      }      // Extract required fields      final String premise = getAddressComponent('premise') ?? '';      final String subLocality2 =          getAddressComponent('sublocality_level_2') ?? '';      final String subLocality1 =          getAddressComponent('sublocality_level_1') ?? '';      final String pinCode = getAddressComponent('postal_code') ?? '';      final String state =          getAddressComponent('administrative_area_level_1') ?? '';      // Combine values for the address      final String address1 =      [subLocality2, subLocality1].where((e) => e.isNotEmpty).join(', ');      // Build and return the LocationModel      return LocationModel(          address1: address1,          address2: premise,          state: state,          pinCode: pinCode.isNotEmpty ? int.parse(pinCode) : null,          latitude: latitude,          longitude: longitude);    } catch (e, stackTrace) {      return null;    }  }}